import java.io.IOException;

public final class CheckCheckout {
    public static void main(String[] args) throws Exception {
        if (exec("javac", "com/optarena/checkout/Checkout.java", "com/optarena/checkout/CheckoutTest.java") != 0) {
            System.err.println("compilation failed");
            System.exit(1);
        }
        System.exit(exec("java", "-ea", "com.optarena.checkout.CheckoutTest"));
    }

    static int exec(String... cmd) throws IOException, InterruptedException {
        return new ProcessBuilder(cmd).inheritIO().start().waitFor();
    }
}

